import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Tesis central del antidepredacionismo","description":"","frontmatter":{},"headers":[],"relativePath":"es/0004-反掠夺主义核心论纲.md","filePath":"es/0004-反掠夺主义核心论纲.md"}'),s={name:"es/0004-反掠夺主义核心论纲.md"};function d(r,e,l,t,c,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="tesis-central-del-antidepredacionismo" tabindex="-1">Tesis central del antidepredacionismo <a class="header-anchor" href="#tesis-central-del-antidepredacionismo" aria-label="Permalink to &quot;Tesis central del antidepredacionismo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>04</td></tr><tr><td>Módulo</td><td>Principios Generales y Parámetros Fundamentales</td></tr><tr><td>Palabras clave</td><td>Antidepredación, Crítica de la depredación, Alternativa simbiótica, Línea roja ética, Revolución sistémica</td></tr></tbody></table><h2 id="i-definicion-y-manifestaciones-del-predacionismo" tabindex="-1">I. Definición y Manifestaciones del Predacionismo <a class="header-anchor" href="#i-definicion-y-manifestaciones-del-predacionismo" aria-label="Permalink to &quot;I. Definición y Manifestaciones del Predacionismo&quot;">​</a></h2><p>El predacionismo es una visión cósmica y un sistema de cultivo que toma como medios centrales la apropiación no compensada, la devoración y la explotación del Origen, la energía, la fortuna y los recursos de otras vidas o planos, con el objetivo de lograr la propia evolución o la del propio grupo. El predacionismo no es una técnica de cultivo específica, sino una postura fundamental que atraviesa la filosofía del cultivo, las instituciones sociales y las relaciones civilizatorias.</p><p>En la historia de Heng Yuan Zhou, el predacionismo se ha manifestado en las siguientes formas principales:</p><table tabindex="0"><thead><tr><th>Forma</th><th>Manifestación</th><th>Daño</th></tr></thead><tbody><tr><td>Depredación de energía</td><td>Devorar directamente la energía de cultivo o el Origen de otras vidas</td><td>Causa la muerte del depredado o la pérdida total de su cultivo; la circulación de energía cósmica se corta</td></tr><tr><td>Depredación de fortuna</td><td>Robar la fortuna de otros o de razas enteras mediante artes secretas</td><td>Causa el colapso del destino del depredado y el declive racial</td></tr><tr><td>Monopolio de métodos</td><td>Unas pocas sectas monopolizan los métodos de cultivo, intercambiando transmisión por lealtad y recursos</td><td>Causa la solidificación de clases; los seres inferiores pierden sus caminos evolutivos</td></tr><tr><td>Colonización de planos</td><td>Planos superiores conquistan planos inferiores, saqueando sus recursos y poblaciones</td><td>Daña la membrana del plano y colapsa los ecosistemas del plano</td></tr><tr><td>Esclavización espiritual</td><td>Convertir otras vidas en herramientas de cultivo mediante el control del alma</td><td>Priva al esclavizado del libre albedrío, violando la dignidad de la vida</td></tr><tr><td>Agotamiento de recursos</td><td>Explotación sin límites de los recursos de un planeta o plano</td><td>Causa extinción ecológica y aceleración de la entropía cósmica</td></tr></tbody></table><h2 id="ii-las-falacias-fundamentales-del-predacionismo" tabindex="-1">II. Las Falacias Fundamentales del Predacionismo <a class="header-anchor" href="#ii-las-falacias-fundamentales-del-predacionismo" aria-label="Permalink to &quot;II. Las Falacias Fundamentales del Predacionismo&quot;">​</a></h2><p>El antidepredacionismo sostiene que el predacionismo contiene tres falacias fundamentales:</p><h3 id="_2-1-falacia-de-la-vision-cosmica-tratar-el-universo-como-un-coto-de-caza-finito" tabindex="-1">2.1 Falacia de la visión cósmica: tratar el universo como un coto de caza finito <a class="header-anchor" href="#_2-1-falacia-de-la-vision-cosmica-tratar-el-universo-como-un-coto-de-caza-finito" aria-label="Permalink to &quot;2.1 Falacia de la visión cósmica: tratar el universo como un coto de caza finito&quot;">​</a></h3><p>La visión cósmica depredadora considera el universo como un coto de caza de recursos finitos, creyendo que la evolución debe ser un juego de suma cero y que el ascenso del fuerte debe lograrse al costo del sacrificio del débil. Esta visión ignora la propia &quot;evolucionabilidad&quot; del universo: el universo no es un contenedor estático de recursos, sino un ser vivo capaz de ascensión dimensional global mediante la simbiosis ordenada. Cuando los depredadores devoran a los débiles, consumen no solo la energía de los débiles, sino el potencial evolutivo del universo en su conjunto.</p><h3 id="_2-2-falacia-etica-colocar-el-derecho-del-fuerte-a-evolucionar-por-encima-del-derecho-del-debil-a-sobrevivir" tabindex="-1">2.2 Falacia ética: colocar el derecho del fuerte a evolucionar por encima del derecho del débil a sobrevivir <a class="header-anchor" href="#_2-2-falacia-etica-colocar-el-derecho-del-fuerte-a-evolucionar-por-encima-del-derecho-del-debil-a-sobrevivir" aria-label="Permalink to &quot;2.2 Falacia ética: colocar el derecho del fuerte a evolucionar por encima del derecho del débil a sobrevivir&quot;">​</a></h3><p>El predacionismo toma &quot;el fuerte devora al débil&quot; como ley natural, creyendo que el fuerte tiene el derecho e incluso la obligación de devorar al débil. Esta visión ética confunde la selección natural con la elección moral. En la naturaleza, que el fuerte devore al débil es una ley ecológica inconsciente; pero en civilizaciones de cultivo conscientes, el fuerte posee la capacidad de elegir y, por tanto, soporta la responsabilidad de la elección. La depredación disfrazada de &quot;Vía del Cielo&quot; es esencialmente el fuerte presentando su propia codicia como ley cósmica.</p><h3 id="_2-3-falacia-de-eficiencia-creer-que-la-depredacion-es-el-camino-evolutivo-mas-rapido" tabindex="-1">2.3 Falacia de eficiencia: creer que la depredación es el camino evolutivo más rápido <a class="header-anchor" href="#_2-3-falacia-de-eficiencia-creer-que-la-depredacion-es-el-camino-evolutivo-mas-rapido" aria-label="Permalink to &quot;2.3 Falacia de eficiencia: creer que la depredación es el camino evolutivo más rápido&quot;">​</a></h3><p>El predacionismo afirma que la depredación es el camino evolutivo más rápido y eficiente. Sin embargo, a largo plazo, la evolución depredadora sufre un grave &quot;techo de eficiencia&quot;: primero, la energía obtenida por depredación suele portar la voluntad residual de su dueño original, exigiendo enormes esfuerzos de refinamiento y purificación; segundo, los actos depredadores provocan resistencia del depredado y sus grupos afiliados, aumentando los costos externos del cultivo; tercero, la dependencia prolongada de la depredación degrada la capacidad evolutiva basada en el Origen del propio cultivador, llevándolo al estancamiento cuando la presa no está disponible; cuarto, los cultivadores depredadores a menudo enfrentan el cuello de botella del &quot;Origen impuro&quot; al irrumpir hacia el reino supremo, dificultando tocar verdaderamente el Origen cósmico.</p><h2 id="iii-proposiciones-centrales-del-antidepredacionismo" tabindex="-1">III. Proposiciones Centrales del Antidepredacionismo <a class="header-anchor" href="#iii-proposiciones-centrales-del-antidepredacionismo" aria-label="Permalink to &quot;III. Proposiciones Centrales del Antidepredacionismo&quot;">​</a></h2><p>El antidepredacionismo no niega simplemente toda competencia y diferencia, sino que propone las siguientes proposiciones centrales:</p><ol><li><strong>La evolución puede ser de suma no cero</strong>: mediante ciclos simbióticos y la red de anclas, la evolución de las Diez Mil Razas puede producir efectos sinérgicos, logrando una eficacia evolutiva donde el todo supera la suma de las partes.</li><li><strong>La competencia debe ser creativa en lugar de destructiva</strong>: el antidepredacionismo no se opone a la competencia sana, pero la competencia debe tomar la forma de mejorar la propia capacidad creativa, no de eliminar la capacidad depredadora del adversario.</li><li><strong>La responsabilidad del fuerte es mayor que sus derechos</strong>: cuanto más alto es el reino de un cultivador, mayor es su responsabilidad hacia la red simbiótica, no mayor su derecho a depredar. Los cultivadores avanzados tienen la obligación de guiar a los junior, mantener la estabilidad de las anclas y proteger la seguridad civilizatoria.</li><li><strong>Los recursos deben aumentarse mediante la creación en lugar de distribuirse mediante la depredación</strong>: el enfoque central de la civilización simbiótica es agrandar el pastel en lugar de dividirlo, creando continuamente nuevos recursos de cultivo mediante el progreso tecnológico y la aplicación de leyes.</li><li><strong>El antidepredacionismo no es igualitarismo</strong>: el antidepredacionismo se opone a la depredación sin trabajo, no a las diferencias derivadas de Más Trabajo, Más Recompensa. La civilización simbiótica reconoce las diferencias en los resultados evolutivos, pero insiste en que las diferencias deben originarse en el propio esfuerzo y contribución.</li></ol><h2 id="iv-garantias-institucionales-del-antidepredacionismo" tabindex="-1">IV. Garantías Institucionales del Antidepredacionismo <a class="header-anchor" href="#iv-garantias-institucionales-del-antidepredacionismo" aria-label="Permalink to &quot;IV. Garantías Institucionales del Antidepredacionismo&quot;">​</a></h2><p>El antidepredacionismo no es solo una proposición teórica; tiene una serie de garantías institucionales:</p><ul><li><strong>Garantía legal</strong>: la Constitución Simbiótica y la ley antimonopolio prohíben explícitamente el comportamiento depredador; el Tribunal Simbiótico tiene jurisdicción sobre los casos de depredación</li><li><strong>Garantía mecánica</strong>: el Sistema de Contrato Vinculado a la Producción asegura que la distribución de recursos se base en la contribución y no en la violencia; la red de anclas monitorea los flujos de energía anormales</li><li><strong>Garantía sistémica</strong>: los Trescientos Sistemas de Cultivo del Origen se basan todos en principios de circulación simbiótica; no existen métodos depredadores</li><li><strong>Garantía educativa</strong>: el Sistema de Educación Simbiótica hace de la ética antidepredación una materia obligatoria, erradicando el pensamiento depredador de raíz</li><li><strong>Garantía de supervisión</strong>: la Asamblea de la República de las Diez Mil Razas ha establecido un Comité Antidepredación, encargado de supervisar e investigar el comportamiento depredador</li></ul><h2 id="v-politica-hacia-las-fuerzas-depredadoras-residuales" tabindex="-1">V. Política hacia las Fuerzas Depredadoras Residuales <a class="header-anchor" href="#v-politica-hacia-las-fuerzas-depredadoras-residuales" aria-label="Permalink to &quot;V. Política hacia las Fuerzas Depredadoras Residuales&quot;">​</a></h2><p>Para las fuerzas depredadoras residuales que aún existen en el universo, la civilización simbiótica adopta una política de &quot;aislamiento, transformación y sanción&quot;: los depredadores que aún no han causado daño grave reciben educación ética y transformación sistémica, guiándolos a unirse al sistema simbiótico; los depredadores que rechazan la transformación y continúan dañando el orden simbiótico son sometidos a aislamiento de plano y restricciones de cultivo; los depredadores que han causado grandes catástrofes son sancionados conforme a la ley. La civilización simbiótica no aboga por combatir la depredación con depredación; todas las sanciones deben pasar por el juicio justo del Tribunal Simbiótico.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El antidepredacionismo es una de las piedras angulares teóricas de la Civilización Simbiótica del Ancla. No es solo una crítica del viejo sistema depredador, sino una construcción positiva de la posibilidad de la evolución simbiótica. El objetivo último del antidepredacionismo no es eliminar a los fuertes, sino hacer que el poder de los fuertes sirva a la evolución común de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Declaración de la Civilización Simbiótica del Ancla)</li><li>03-共生文明宪章 (Carta de la Civilización Simbiótica)</li><li>19-修炼伦理与边界 (Ética del Cultivo y Límites)</li></ul>',26)])])}const v=a(s,[["render",d]]);export{m as __pageData,v as default};
